function dump(n, depth){
  let s = "  ".repeat(depth) + n.type + " | " + n.name + " | " + Math.round(n.width) + "x" + Math.round(n.height);
  if (n.type === "TEXT") s += " | chars=" + JSON.stringify(n.characters) + " | font=" + (n.fontName && n.fontName.family ? n.fontName.family+" "+n.fontName.style : "mixed") + " | size=" + (typeof n.fontSize === "number" ? n.fontSize : "mixed");
  if ("fills" in n && Array.isArray(n.fills) && n.fills.length) {
    const f = n.fills[0];
    s += " | fill=" + f.type + (f.type==="SOLID" ? " #"+[f.color.r,f.color.g,f.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("") + " a=" + (f.opacity!==undefined?f.opacity:1) : "");
  }
  if ("cornerRadius" in n && n.cornerRadius) s += " | r=" + n.cornerRadius;
  if ("strokes" in n && n.strokes && n.strokes.length) s += " | stroke=" + JSON.stringify(n.strokes[0].color);
  out.push(s);
  if ("children" in n && depth < 4) for (const c of n.children) dump(c, depth+1);
}
