function T(chars,size,style,color,opts){
  const t=figma.createText(); t.fontName={family:"Poppins",style:style||"Regular"};
  t.characters=chars; t.fontSize=size; t.fills=[{type:"SOLID",color:color||C.TXT}];
  if(opts&&opts.lh) t.lineHeight={value:opts.lh,unit:"PIXELS"};
  if(opts&&opts.ls) t.letterSpacing={value:opts.ls,unit:"PIXELS"};
  if(opts&&opts.align) t.textAlignHorizontal=opts.align;
  if(opts&&opts.name) t.name=opts.name;
  if(opts&&opts.w){ t.textAutoResize="HEIGHT"; t.resize(opts.w,t.height); }
  return t;
}
function F(name,mode,gap,pad,fill,radius){
  const f=figma.createFrame(); f.name=name;
  if(mode){f.layoutMode=mode;f.itemSpacing=gap||0;
    if(pad){f.paddingLeft=pad[0];f.paddingRight=pad[0];f.paddingTop=pad[1];f.paddingBottom=pad[1];}}
  f.fills=fill?[{type:"SOLID",color:fill}]:[];
  if(radius) f.cornerRadius=radius;
  return f;
}
function screen(name,h){
  const s=figma.createFrame(); s.name=name; s.resize(375,h||812);
  s.fills=[{type:"SOLID",color:C.BG}]; s.clipsContent=true;
  s.layoutMode="VERTICAL"; s.primaryAxisSizingMode="FIXED"; s.counterAxisSizingMode="FIXED";
  s.itemSpacing=0; s.paddingLeft=0;s.paddingRight=0;s.paddingTop=0;s.paddingBottom=0;
  page.appendChild(s); return s;
}
