const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const out=[];
for(const nm of ["01_Get_Started","02_Onboarding","03_Log_In","04_Verify_Email"]){
  const s=page.children.find(n=>n.name===nm);
