  const insts=s.findAll(n=>n.type==="INSTANCE").map(i=>i.name);
  out.push("====="+nm+"=====\nTEXTS: "+texts.join(" | ")+"\nINSTANCES: "+insts.join(", "));
}
return out.join("\n\n");

const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const out=[];
for(const s of page.children.filter(n=>/^\d\d_/.test(n.name))){
  const rs=[];
  s.findAll(n=>n.reactions&&n.reactions.length>0).forEach(n=>{
    for(const r of n.reactions){
      if(r.action&&r.action.type==="NODE") rs.push(n.name+" -> "+(r.action.destinationId?figma.getNodeById(r.action.destinationId).name:"?"));
    }
  });
  out.push(s.name+": "+(rs.length?rs.join(" ; "):"NONE"));
}
return out.join("\n");

const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
