const log=[];
function link(srcName, node, destName){
  try{
    node.reactions=[...node.reactions, {trigger:{type:"ON_CLICK"}, actions:[{type:"NODE", destinationId:S[destName].id, navigation:"NAVIGATE", transition:{type:"SMART_ANIMATE", duration:0.3, easing:{type:"EASE_IN_AND_OUT"}}}]}];
    log.push("OK "+srcName+"/"+node.name+" -> "+destName);
  }catch(e){ log.push("FAIL "+srcName+"/"+node.name+": "+e.message); }
}
