const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const S={};
for(const s of page.children) if(/^\d\d_/.test(s.name)) S[s.name]=s;
const s10=S["10_Account_Updated"];
const modal=s10.findOne(n=>n.name==="Modal");
const btn=modal.findOne(n=>n.name==="Button");
const label=btn.findOne(n=>n.type==="TEXT");
await figma.loadFontAsync(label.fontName);
label.characters="Ok";
btn.reactions=[{trigger:{type:"ON_CLICK"}, actions:[{type:"NODE", destinationId:S["05_Home"].id, navigation:"NAVIGATE", transition:{type:"SMART_ANIMATE", duration:0.3, easing:{type:"EASE_IN_AND_OUT"}}}]}];
// verify all reactions
const out=[];
for(const s of page.children.filter(n=>/^\d\d_/.test(n.name))){
  const rs=[];
  s.findAll(n=>n.reactions&&n.reactions.length>0).forEach(n=>{
