const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const out=["Page: "+page.name+" ("+page.id+")"];
for(const s of page.children){
  out.push(s.type+" "+s.name+" id:"+s.id+" @"+Math.round(s.x)+","+Math.round(s.y)+" "+Math.round(s.width)+"x"+Math.round(s.height));
}
// reference pages intact?
for(const p of figma.root.children){
  if(!p.name.includes("03")) out.push("REF "+p.name+": "+p.children.length+" top nodes");
}
return out.join("\n");
